DROP POLICY tenant_module_config_write_super_admin ON public.tenant_module_config;
CREATE POLICY tenant_module_config_write_console ON public.tenant_module_config FOR ALL TO authenticated
  USING (public.user_has_console_perm('console.tenants.manage'))
  WITH CHECK (public.user_has_console_perm('console.tenants.manage'));

CREATE FUNCTION public.pin_credential_request_identity() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status NOT IN ('draft','returned') AND (NEW.resident_id, NEW.request_type, NEW.household_id, NEW.issuing_kebele_id)
     IS DISTINCT FROM (OLD.resident_id, OLD.request_type, OLD.household_id, OLD.issuing_kebele_id) THEN
    RAISE EXCEPTION 'credential_request identity fields are immutable after submission';
  END IF; RETURN NEW; END $$;
CREATE TRIGGER aa_pin_credential_request_identity BEFORE UPDATE ON public.credential_request FOR EACH ROW EXECUTE FUNCTION public.pin_credential_request_identity();

DROP POLICY credential_request_update ON public.credential_request;
CREATE POLICY credential_request_update ON public.credential_request FOR UPDATE TO authenticated
  USING (is_super_admin() OR (woreda_id = get_user_woreda_id() AND user_has_any_perm('{credential.issue,credential.review,credential.approve,credential.return,credential.reject,credential.record_payment,credential.confirm_print,credential.activate}')))
  WITH CHECK (same);

CREATE FUNCTION public.module_enabled(_w uuid, _k text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$
  SELECT COALESCE((SELECT is_enabled FROM tenant_module_config WHERE woreda_id=_w AND module_key=_k), true) $$;
